        function createProceduralFloorTexture(pal = {}) {
            const fBase = pal.floorBase || '#0a1020', fLine = pal.floorLine || '#1e293b', fAcc = pal.accent || '#00f0ff';
            const canvas = document.createElement('canvas');
            canvas.width = 512;
            canvas.height = 512;
            const ctx = canvas.getContext('2d');

            ctx.fillStyle = fBase;
            ctx.fillRect(0, 0, 512, 512);

            ctx.strokeStyle = fLine;
            ctx.lineWidth = 6;
            const tileSize = 64;
            for (let x = 0; x <= 512; x += tileSize) {
                ctx.beginPath();
                ctx.moveTo(x, 0);
                ctx.lineTo(x, 512);
                ctx.stroke();
            }
            for (let y = 0; y <= 512; y += tileSize) {
                ctx.beginPath();
                ctx.moveTo(0, y);
                ctx.lineTo(512, y);
                ctx.stroke();
            }

            ctx.strokeStyle = fAcc; ctx.globalAlpha = 0.25;
            ctx.lineWidth = 2;
            ctx.strokeRect(4, 4, 504, 504);
            ctx.globalAlpha = 1;

            ctx.fillStyle = fAcc;
            for (let x = 0; x <= 512; x += tileSize) {
                for (let y = 0; y <= 512; y += tileSize) {
                    ctx.fillRect(x - 2, y - 2, 4, 4);
                }
            }

            const texture = new THREE.CanvasTexture(canvas);
            texture.wrapS = THREE.RepeatWrapping;
            texture.wrapT = THREE.RepeatWrapping;
            texture.repeat.set(1, 1); // jede Bodenzelle hat eigene UVs
            return texture;
        }

        function createProceduralWallTexture(pal = {}) {
            const wBase = pal.wallBase || '#111827', wBorder = pal.wallBorder || '#374151', wAcc = pal.accent || '#00f0ff', wRivet = pal.wallRivet || '#4b5563';
            const canvas = document.createElement('canvas');
            canvas.width = 512;
            canvas.height = 512;
            const ctx = canvas.getContext('2d');

            ctx.fillStyle = wBase;
            ctx.fillRect(0, 0, 512, 512);

            ctx.strokeStyle = wBorder;
            ctx.lineWidth = 8;
            ctx.strokeRect(8, 8, 496, 496);
            ctx.strokeRect(64, 64, 384, 384);

            ctx.strokeStyle = wAcc; ctx.globalAlpha = 0.4;
            ctx.lineWidth = 4;
            ctx.beginPath();
            ctx.moveTo(0, 256);
            ctx.lineTo(512, 256);
            ctx.stroke();
            ctx.globalAlpha = 1;

            ctx.fillStyle = wAcc;
            ctx.fillRect(30, 246, 50, 20);
            ctx.fillRect(432, 246, 50, 20);

            ctx.fillStyle = wRivet;
            const rivets = [[24, 24], [488, 24], [24, 488], [488, 488], [80, 80], [432, 80], [80, 432], [432, 432]];
            rivets.forEach(([cx, cy]) => {
                ctx.beginPath();
                ctx.arc(cx, cy, 6, 0, Math.PI * 2);
                ctx.fill();
            });

            const texture = new THREE.CanvasTexture(canvas);
            texture.wrapS = THREE.RepeatWrapping;
            texture.wrapT = THREE.RepeatWrapping;
            return texture;
        }

