        const PERF = { maxRatio: Math.min(window.devicePixelRatio || 1, LOW_END ? 1 : 1.5), minRatio: LOW_END ? 0.55 : 0.75, ratio: 1, frames: 0, acc: 0 };
        PERF.ratio = PERF.maxRatio;
