        function perfTick(dt) {
            PERF.frames++; PERF.acc += dt;
            if (PERF.acc < 2) return;
            const fps = PERF.frames / PERF.acc; PERF.frames = 0; PERF.acc = 0;
            let nr = PERF.ratio;
            if (fps < 45) nr = Math.max(PERF.minRatio, PERF.ratio - 0.15);
            else if (fps > 57) nr = Math.min(PERF.maxRatio, PERF.ratio + 0.1);
            if (Math.abs(nr - PERF.ratio) > 0.01) { PERF.ratio = nr; renderer.setPixelRatio(nr); renderer.setSize(window.innerWidth, window.innerHeight); }
        }
