function gridFrom(o) {
    const N = MAZE_GRID_SIZE, g = Array.from({ length: N }, () => Array(N).fill(0));
    if (o.border) for (let i = 0; i < N; i++) { g[0][i] = g[N - 1][i] = g[i][0] = g[i][N - 1] = 1; }
    (o.rects || []).forEach(([r0, c0, r1, c1, v = 1]) => {
        for (let r = r0; r <= r1; r++) for (let c = c0; c <= c1; c++) {
            g[r][c] = g[N - 1 - r][c] = g[r][N - 1 - c] = g[N - 1 - r][N - 1 - c] = v;
        }
    });
    if (o.radius) for (let r = 0; r < N; r++) for (let c = 0; c < N; c++) if (Math.hypot(r - 12, c - 12) > o.radius) g[r][c] = 2;
    return g;
}
