        function createPlayerMesh(name, skinId) {
            const skin = getSkin(skinId);
            const group = new THREE.Group();

            // Emissive, damit der Skin auch im Dunkeln deutlich leuchtet
            const bodyMat = new THREE.MeshStandardMaterial({
                color: skin.body, emissive: skin.body, emissiveIntensity: 0.55, roughness: 0.35, metalness: 0.3
            });
            const visorMat = new THREE.MeshBasicMaterial({ color: skin.visor });

            const torso = new THREE.Mesh(new THREE.CylinderGeometry(0.4, 0.3, 1.2, 10), bodyMat);
            torso.position.y = 0.9;
            group.add(torso);

            const head = new THREE.Mesh(new THREE.SphereGeometry(0.3, 16, 16), bodyMat);
            head.position.y = 1.7;
            group.add(head);

            const visor = new THREE.Mesh(new THREE.BoxGeometry(0.32, 0.12, 0.25), visorMat);
            visor.position.set(0, 1.72, -0.18);
            group.add(visor);

            const remoteGun = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.15, 0.5), new THREE.MeshStandardMaterial({ color: 0x334155 }));
            remoteGun.position.set(0.4, 1.0, -0.3);
            group.add(remoteGun);

            // Leuchtring am Boden hebt Spieler vom dunklen Boden ab
            const ring = new THREE.Mesh(
                new THREE.RingGeometry(0.55, 0.75, 28),
                new THREE.MeshBasicMaterial({ color: skin.body, side: THREE.DoubleSide, transparent: true, opacity: 0.85 })
            );
            ring.rotation.x = -Math.PI / 2;
            ring.position.y = 0.04;
            group.add(ring);

            // Nametag in Skinfarbe
            const canvas = document.createElement('canvas');
            canvas.width = 256;
            canvas.height = 64;
            const ctx = canvas.getContext('2d');
            ctx.fillStyle = 'rgba(5, 9, 20, 0.85)';
            ctx.fillRect(0, 0, 256, 64);
            ctx.strokeStyle = hexStr(skin.body);
            ctx.lineWidth = 4;
            ctx.strokeRect(2, 2, 252, 60);
            ctx.font = 'bold 26px Orbitron, sans-serif';
            ctx.fillStyle = hexStr(skin.body);
            ctx.textAlign = 'center';
            ctx.fillText(name, 128, 42);

            const tagTex = new THREE.CanvasTexture(canvas);
            const tagSprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: tagTex, depthTest: !cheats.wallhack }));
            tagSprite.position.y = 2.4;
            tagSprite.scale.set(1.8, 0.45, 1);
            tagSprite.renderOrder = cheats.wallhack ? 1000 : 0;
            group.add(tagSprite);

            // Wallhack-ESP: Drahtgitter + Box, wird auch durch Wände gezeichnet
            const esp = new THREE.Group();
            const espMat = new THREE.MeshBasicMaterial({ color: 0xff2d2d, wireframe: true, transparent: true, opacity: 0.9, depthTest: false, depthWrite: false, fog: false });
            const espTorso = new THREE.Mesh(torso.geometry, espMat);
            espTorso.position.copy(torso.position);
            const espHead = new THREE.Mesh(head.geometry, espMat);
            espHead.position.copy(head.position);
            const espBox = new THREE.LineSegments(
                new THREE.EdgesGeometry(new THREE.BoxGeometry(1.0, 2.2, 1.0)),
                new THREE.LineBasicMaterial({ color: 0xff2d2d, depthTest: false, depthWrite: false, transparent: true, fog: false })
            );
            espBox.position.y = 1.1;
            [espTorso, espHead, espBox].forEach(m => { m.renderOrder = 999; esp.add(m); });
            esp.visible = cheats.wallhack;
            group.add(esp);

            group.userData.esp = esp;
            group.userData.tag = tagSprite;
            return group;
        }

