        function tryDash() {
            if (!canPlay()) return;
            if (player.dashCool > 0 || player.dashTime > 0) return;
            if (player.stamina < DASH_COST) {
                addKillFeed('Zu wenig Stamina!');
                return;
            }
            const forward = new THREE.Vector3(-Math.sin(player.yaw), 0, -Math.cos(player.yaw));
            const right = new THREE.Vector3(Math.cos(player.yaw), 0, -Math.sin(player.yaw));
            const dir = new THREE.Vector3();
            if (keys.w) dir.add(forward);
            if (keys.s) dir.sub(forward);
            if (keys.d) dir.add(right);
            if (keys.a) dir.sub(right);
            dir.addScaledVector(forward, analog.y).addScaledVector(right, analog.x);
            if (dir.lengthSq() === 0) dir.copy(forward);
            dir.normalize();

            player.dashDir.copy(dir);
            player.dashTime = DASH_TIME;
            player.dashCool = DASH_COOLDOWN;
            player.staminaDelay = REGEN_DELAY;
            if (!cheats.infStamina) player.stamina -= DASH_COST;
            audio.playDash();
            updateStaminaUI();
        }

        // ----- Spawn -----
        function placeAtSpawn() {
            // Spawnpunkt wählen, der möglichst weit von Gegnern entfernt ist
            let best = null, bestScore = -1;
            for (const sp of SPAWN_POINTS) {
                let minD = 60;
                for (const id in remotePlayers) {
                    const m = remotePlayers[id].mesh.position;
                    minD = Math.min(minD, Math.hypot(sp.x - m.x, sp.z - m.z));
                }
                const score = minD + Math.random() * 15;
                if (score > bestScore) { bestScore = score; best = sp; }
            }
            if (best) {
                player.pos.set(best.x, player.height, best.z);
                player.yaw = Math.atan2(best.x, best.z); // zur Mitte schauen
            } else {
                player.pos.set(0, player.height, 0);
            }
            player.pitch = 0;
            player.protectUntil = performance.now() + SPAWN_PROTECT_MS;
        }

